import{_ as t,o as a,c as o,a2 as l}from"./chunks/framework.C2TvIV46.js";const h=JSON.parse('{"title":"Compiler settings","description":"","frontmatter":{},"headers":[],"relativePath":"language/compiler-settings.md","filePath":"language/compiler-settings.md"}'),r={name:"language/compiler-settings.md"};function d(i,e,s,n,c,g){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="compiler-settings" tabindex="-1">Compiler settings <a class="header-anchor" href="#compiler-settings" aria-label="Permalink to &quot;Compiler settings&quot;">​</a></h1><p>Megalo source does not declare these options — they are <strong>compile-time switches</strong> that change how strictly the compiler interprets your script. The same <code>.txt</code> file can produce errors, warnings, or different variable allocation depending on which mode the editor uses.</p><p>HREK <strong>MegaloEdit</strong> always compiles in <strong>lenient mode</strong> (permissive defaults). Bungie&#39;s internal build farm probably used stricter settings. The switches live in <strong>ManagedMegalo.dll</strong> (<code>ParsingHelper</code>, <code>MegaloCompiler</code>); MegaloEdit wires them in but does not expose them in the UI.</p><p>MegaloEdit also exposes <strong>input</strong> and <strong>output directory</strong> settings (File → Settings). These paths control where the compiler looks for external files:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Used when resolving</th></tr></thead><tbody><tr><td><strong>Input directory</strong></td><td><a href="/MegaloEvolved/beta/docs/language/elements/include"><code>include</code></a> and <a href="/MegaloEvolved/beta/docs/language/elements/localized-include"><code>localized_include</code></a> paths</td></tr><tr><td><strong>Output directory</strong></td><td><a href="/MegaloEvolved/beta/docs/language/elements/base"><code>base</code></a> references to compiled <code>.mglo</code> files</td></tr></tbody></table><p>Include paths in source are relative to the input directory (and the including file). Base paths name a compiled variant in the output directory — by default <code>maps/megalo</code> under the HREK install when using MegaloEdit.exe. Compile the parent script first so its <code>.mglo</code> exists before building a derived script that references it. See <a href="/MegaloEvolved/beta/docs/language/base-files">Base files</a>.</p><h2 id="localized-include-strictness" tabindex="-1">localized_include strictness <a class="header-anchor" href="#localized-include-strictness" aria-label="Permalink to &quot;localized_include strictness&quot;">​</a></h2><p>Controls whether a missing <a href="/MegaloEvolved/beta/docs/language/elements/localized-include"><code>localized_include</code></a> is optional or fatal.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Missing file behavior</th></tr></thead><tbody><tr><td><strong>Lenient</strong> (MegaloEdit)</td><td>Warning, include skipped — compile continues</td></tr><tr><td><strong>Strict</strong></td><td>Hard error, same as a missing plain <a href="/MegaloEvolved/beta/docs/language/elements/include"><code>include</code></a></td></tr></tbody></table><p>When the file exists, behavior is identical in both modes.</p><p>MegaloEdit always uses lenient mode. See <a href="/MegaloEvolved/beta/docs/language/elements/localized-include"><code>localized_include</code></a>.</p><p><em>ManagedMegalo.dll: <code>enforceLocalizedIncludes</code> on <code>ParsingHelper</code>.</em></p><h2 id="string-literal-strictness" tabindex="-1">String literal strictness <a class="header-anchor" href="#string-literal-strictness" aria-label="Permalink to &quot;String literal strictness&quot;">​</a></h2><p>Controls whether <strong>quoted literal strings</strong> in places that expect a string-table symbol are allowed.</p><p>Many elements require string table tokens — <code>engine_data name slayer_title</code>, not <code>engine_data name &quot;Slayer&quot;</code>. In lenient mode, a literal still compiles but produces a warning:</p><blockquote><p><em>You used a literal string &#39;…&#39;. Fix this before you submit. The build farm enforces localization.</em></p></blockquote><p>In strict mode, the same literal is a <strong>hard error</strong>. Strict mode also blocks quoted strings anywhere the parser is enforcing localization.</p><p>MegaloEdit always uses lenient mode. Shipped Reach scripts use string-table symbols throughout.</p><p><em>ManagedMegalo.dll: <code>enforceLocalization</code> on <code>ParsingHelper</code>.</em></p><h2 id="temporary-variable-overflow" tabindex="-1">Temporary variable overflow <a class="header-anchor" href="#temporary-variable-overflow" aria-label="Permalink to &quot;Temporary variable overflow&quot;">​</a></h2><p>A <strong><code>temporary</code></strong> is a scratch variable declared inside a trigger or <code>for_each</code> block with the <code>temporary</code> keyword. It exists only for the duration of that block&#39;s execution — useful for holding getter results or intermediate values without declaring a permanent <a href="/MegaloEvolved/beta/docs/language/elements/variables"><code>variables</code></a> slot. See <a href="/MegaloEvolved/beta/docs/language/variable-model#temporary-variables">Variable model — Temporary variables</a>.</p><p>Temporary allocation has changed across Megalo versions:</p><ul><li><strong>Originally</strong> — when <code>temporary</code> was introduced, the compiler treated temporaries as <strong>global variables</strong>, allocating them directly from the global variable pool.</li><li><strong>Halo 4</strong> — added a <strong>dedicated temporaries pool</strong>, effectively increasing how many scratch variables a trigger could use without consuming globals.</li><li><strong>Reach MCC</strong> — that separate pool was <strong>backported</strong> from Halo 4. Xbox 360 TU1 Reach still uses the original global-mapping behavior.</li></ul><p>This overflow setting only applies to Megalo versions <strong>after Xbox 360 TU1</strong> (Reach MCC and later). On TU1, temporaries already map to globals — there is no separate pool to overflow from.</p><p>On MCC Reach, each <a href="/MegaloEvolved/beta/docs/language/elements/trigger#action-scope">action scope</a> has a fixed dedicated temporary pool per type. Per scope:</p><table tabindex="0"><thead><tr><th>Type</th><th>Dedicated pool</th><th>Max overflow into globals</th></tr></thead><tbody><tr><td><code>number</code></td><td>10</td><td>12</td></tr><tr><td><code>object</code></td><td>8</td><td>16</td></tr><tr><td><code>team</code></td><td>6</td><td>8</td></tr><tr><td><code>player</code></td><td>3</td><td>8</td></tr></tbody></table><p>When overflow is <strong>enabled</strong> (MegaloEdit default), the compiler may spill excess temporaries into <strong>unused global variable slots</strong> of the same type once the dedicated pool is full, up to the overflow cap. When overflow is <strong>disabled</strong>, running out of temporary slots fails the compile.</p><p>This affects how much logic you can pack into a single scope — not syntax, but whether deeply nested <code>temporary</code> declarations are accepted. See <a href="/MegaloEvolved/beta/docs/versions/107-mcc/#limits">107 (MCC) — Limits</a> and <a href="/MegaloEvolved/beta/docs/versions/107/#limits">107 — Limits</a> for scope nesting and TU1 behavior.</p><p><em>ManagedMegalo.dll: <code>TemporaryVariablesCanOverflowIntoUnusedGlobalVariables</code> on <code>MegaloCompiler</code>.</em></p><p>See also <a href="/MegaloEvolved/beta/docs/guide/megalo-versions">Megalo versions</a> (MCC vs TU1).</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Lenient (MegaloEdit)</th><th>Strict</th><th>Language feature</th></tr></thead><tbody><tr><td>Input directory</td><td>—</td><td>—</td><td><a href="/MegaloEvolved/beta/docs/language/elements/include"><code>include</code></a>, <a href="/MegaloEvolved/beta/docs/language/elements/localized-include"><code>localized_include</code></a></td></tr><tr><td>Output directory</td><td>—</td><td>—</td><td><a href="/MegaloEvolved/beta/docs/language/elements/base"><code>base</code></a> (<code>.mglo</code> lookup)</td></tr><tr><td>Localized includes</td><td>Missing file → warning</td><td>Missing file → error</td><td><a href="/MegaloEvolved/beta/docs/language/elements/localized-include"><code>localized_include</code></a></td></tr><tr><td>String literals</td><td>Warning</td><td>Error</td><td>String-table symbols vs <code>&quot;quoted&quot;</code> text</td></tr><tr><td>Temporary overflow (MCC+)</td><td>Spill into free globals</td><td>Compile fails when pool full</td><td><a href="/MegaloEvolved/beta/docs/language/elements/trigger#action-scope"><code>temporary</code></a> in triggers</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/language/base-files">Base files</a> — derived scripts and <code>.mglo</code> lookup</li><li><a href="/MegaloEvolved/beta/docs/language/elements/localized-include"><code>localized_include</code></a></li><li><a href="/MegaloEvolved/beta/docs/language/syntax#includes">Syntax — Includes</a></li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger#action-scope">trigger — Action scope</a></li><li><a href="/MegaloEvolved/beta/docs/language/variable-model#temporary-variables">Variable model — Temporary variables</a></li><li><a href="/MegaloEvolved/beta/docs/guide/megalo-versions">Megalo versions</a> — MCC vs Xbox 360 TU1</li></ul>',34)])])}const u=t(r,[["render",d]]);export{h as __pageData,u as default};
